<script setup lang="ts">import{onMounted,ref}from'vue';import{request}from'../api/client';interface Log{id:number;admin:string;action:string;resource_type:string;resource_id:string;reason:string;request_id:string;ip:string;created_at:string}const items=ref<Log[]>([]);onMounted(async()=>items.value=await request<Log[]>('/v1/ops/audit-logs'))</script><template><div class="page"><div class="heading"><div><h1>审计日志</h1><p>所有高风险后台操作均不可静默执行</p></div></div><div class="table"><table><thead><tr><th>管理员</th><th>操作</th><th>资源</th><th>原因</th><th>请求</th><th>时间</th></tr></thead><tbody><tr v-for="v in items" :key="v.id"><td>{{v.admin}}<small>{{v.ip}}</small></td><td>{{v.action}}</td><td>{{v.resource_type}} · {{v.resource_id}}</td><td>{{v.reason}}</td><td><small>{{v.request_id}}</small></td><td>{{new Date(v.created_at).toLocaleString()}}</td></tr></tbody></table></div></div></template><style scoped>@import '../design/admin-page.css';</style>
